import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import "../styles/Profile.css";

const UserViewProfile = () => {
  const { id } = useParams();
  const [user, setUser] = useState(null);
  const [profile, setProfile] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/profile/${id}`);
        setUser(res.data.user);
        setProfile(res.data.profile);
      } catch (err) {
        console.error("Error fetching profile:", err);
      }
    };
    fetchProfile();
  }, [id]);

  return (
    <div className="profile-container">
      <h2 className="profile-title">User Profile</h2>

      {user && (
        <>
          <p><b>Username:</b> {user.username}</p>
          <p><b>Email:</b> {user.email}</p>
        </>
      )}

      {profile ? (
        <>
          <p><b>Bio:</b> {profile.bio || "None"}</p>
          <p><b>Genres:</b> {profile.genres?.join(", ") || "None"}</p>
          <p><b>Instruments:</b> {profile.instruments?.join(", ") || "None"}</p>
          <p><b>Years of Experience:</b> {profile.yearsOfExperience || "N/A"}</p>
          <p><b>YouTube:</b> {profile.youtube ? <a href={profile.youtube}>{profile.youtube}</a> : "None"}</p>
          <p><b>Instagram:</b> {profile.instagram ? <a href={profile.instagram}>{profile.instagram}</a> : "None"}</p>
        </>
      ) : (
        <p>No profile data.</p>
      )}

      <button className="back-btn" onClick={() => navigate(-1)}>⬅️ Back</button>
    </div>
  );
};

export default UserViewProfile;
